#include "dataReport.h"

/* PNG */
static const wxString s_report_64_png = wxT("");

wxIcon ibValueMetaObjectReport::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectReport::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_report_64_png, wxSize(16, 16));

	return icon;
}
